/* Demonstrates opening a file, writing buffered data, and ensuring proper closure using fclose() with error checking. */
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

int main() {
    const char *filename = "example_data.txt";
    FILE *file_stream = NULL;
    int close_result;

    // 1. Open the file stream for writing
    file_stream = fopen(filename, "w");
    if (file_stream == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    printf("File stream opened for writing.\n");

    // 2. Write data (data is buffered in memory)
    if (fprintf(file_stream, "This data must be flushed by fclose.\n") < 0) {
        perror("Error writing data");
    }

    // 3. Close the file stream
    // This flushes the buffer and closes the underlying file descriptor.
    close_result = fclose(file_stream);

    if (close_result == 0) {
        printf("File '%s' successfully closed (resources freed).\n", filename);
    } else {
        // Handle fclose failure (EOF is returned)
        fprintf(stderr, "Error closing file '%s'. errno: %d (%s)\n", 
                filename, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
